CREATE TABLE public.member_video_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, request_key uuid NOT NULL, source text NOT NULL, status text NOT NULL DEFAULT 'starting' CHECK(status IN ('starting','queued','in_progress','completed','failed','unknown')), gateway_job_id text UNIQUE, billing_transaction_id uuid, estimated_provider_cents numeric NOT NULL DEFAULT 0, media_id uuid, video_url text, error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,request_key)); GRANT SELECT ON public.member_video_jobs TO authenticated; GRANT ALL ON public.member_video_jobs TO service_role; ALTER TABLE public.member_video_jobs ENABLE ROW LEVEL SECURITY; CREATE POLICY "Members read own video jobs" ON public.member_video_jobs FOR SELECT TO authenticated USING(auth.uid()=user_id);